function scopePattern(scope: string): RegExp {
  const normalized = scope.split(sep).join("/");
  const escaped = normalized.replace(/[.+?^${}()|[\]\\]/g, "\\$&");
  const wildcarded = escaped.replaceAll("**", "\u0000").replaceAll("*", "[^/]*").replaceAll("\u0000", ".*");
  return new RegExp(`^${wildcarded}$`);
}

type SourceFile = {
  file: string;
  source: string;
};

function matchesFromSources(sourceFiles: readonly SourceFile[]): RawColourMatch[] {
  const rawColour = /(?<!&)#[\da-f]{3,8}\b|(?:rgb|hsl)a?\((?!\s*var\()[^)]*\)/gi;

  return sourceFiles.flatMap(({ file: fileName, source }) => {
    const lineStarts = [0];
    for (let index = source.indexOf("\n"); index !== -1; index = source.indexOf("\n", index + 1)) {
      lineStarts.push(index + 1);
    }

    return [...source.matchAll(rawColour)].map((match) => {
      const index = match.index ?? 0;
      let lineIndex = lineStarts.length - 1;
      while (lineStarts[lineIndex] > index) lineIndex -= 1;
      const lineStart = lineStarts[lineIndex];
      const lineEnd = source.indexOf("\n", lineStart);
      return {
        file: fileName,
        line: lineIndex + 1,
        column: index - lineStart,
        lineText: source.slice(lineStart, lineEnd === -1 ? source.length : lineEnd),
        value: match[0],
      };
    });
  });
}

function rawColourMatches(): RawColourMatch[] {
  return matchesFromSources(
    files.map((file) => ({
      file: relative(SRC_ROOT, file).split(sep).join("/"),
      source: readFileSync(file, "utf8"),
    })),
  );
}

function rawColourEntry(match: RawColourMatch): RawColourEntry {
  const leadingWhitespace = match.lineText.length - match.lineText.trimStart().length;
  return {
    file: match.file,
    column: Math.max(0, match.column - leadingWhitespace),
    lineText: match.lineText.trim(),
    value: match.value,
  };
}

function encodeSnapshot(matches: readonly RawColourMatch[]): string {
  const tuples = matches
    .map(rawColourEntry)
    .map(({ file, value, lineText, column }) => [file, value, lineText, column] as const)
    .sort((left, right) => JSON.stringify(left).localeCompare(JSON.stringify(right)));
  return deflateRawSync(JSON.stringify(tuples)).toString("base64");
}

function decodeSnapshot(snapshot: string): RawColourEntry[] {
  const tuples = JSON.parse(
    inflateRawSync(Buffer.from(snapshot, "base64")).toString("utf8"),
  ) as Array<[string, string, string, number]>;
  return tuples.map(([file, value, lineText, column]) => ({ file, value, lineText, column }));
}

function exceptionMatches(exception: RawColourException, match: RawColourMatch): boolean {
  return (
    scopePattern(exception.scope).test(match.file) &&
    (!exception.value || exception.value.test(match.value)) &&
    (!exception.line || exception.line.test(match.lineText))
  );
}

function fingerprintFor(matches: readonly RawColourMatch[]): string {
  return createHash("sha256")
    .update(
      matches
        .map((match) => `${match.file}:${match.value.toLowerCase()}:${match.lineText.trim()}`)
        .sort()
        .join("\n"),
    )
    .digest("hex");
}

function exactEntryKey(match: RawColourEntry): string {
  return `${match.file}:${match.value.toLowerCase()}:${match.lineText.trim()}`;
}

function entryIdentity(match: RawColourEntry): string {
  const before = match.lineText.slice(0, match.column).trim();
  const after = match.lineText.slice(match.column + match.value.length).trim();
  return `${match.file}:${before}<colour>${after}`;
}

function formatRawColourEntry(match: RawColourEntry): string {
  return `${match.file}: ${match.value} in "${match.lineText.trim()}"`;
}

function diffRawColourEntries(
  expected: readonly RawColourEntry[],
  actual: readonly RawColourEntry[],
): string {
  const expectedUnmatched = [...expected];
  const actualUnmatched: RawColourEntry[] = [];

  for (const match of actual) {
    const index = expectedUnmatched.findIndex((candidate) => exactEntryKey(candidate) === exactEntryKey(match));
    if (index === -1) actualUnmatched.push(match);
    else expectedUnmatched.splice(index, 1);
  }

  const changed: Array<{ expected: RawColourEntry; actual: RawColourEntry }> = [];
  const added: RawColourEntry[] = [];
  for (const match of actualUnmatched) {
    const index = expectedUnmatched.findIndex((candidate) => entryIdentity(candidate) === entryIdentity(match));
    if (index === -1) added.push(match);
    else {
      changed.push({ expected: expectedUnmatched[index], actual: match });
      expectedUnmatched.splice(index, 1);
    }
  }

  const sections = [
    `Added:\n${added.length ? added.map((match) => `  + ${formatRawColourEntry(match)}`).join("\n") : "  (none)"}`,
    `Removed:\n${
      expectedUnmatched.length
        ? expectedUnmatched.map((match) => `  - ${formatRawColourEntry(match)}`).join("\n")
        : "  (none)"
    }`,
    `Changed:\n${
      changed.length
        ? changed
            .map(
              ({ expected: before, actual: after }) =>
                `  ~ ${before.file}: ${before.value} -> ${after.value} (${after.lineText.trim()})`,
            )
            .join("\n")
        : "  (none)"
    }`,
  ];
  return sections.join("\n");
}

function fingerprintFailureMessage(
  exception: RawColourException,
  expected: ExceptionFingerprint,
  current: readonly RawColourMatch[],
): string {
  return [
    `Raw-colour exception changed; narrow or deliberately update: ${exception.scope}`,
    "Raw-colour diff:",
    diffRawColourEntries(decodeSnapshot(expected.snapshot), current.map(rawColourEntry)),
  ].join("\n");
}

function rewriteFingerprintMap(fingerprints: ReadonlyMap<string, ExceptionFingerprint>): void {
  const originalSource = readFileSync(TEST_FILE, "utf8");
  const mapPattern =
    /const exceptionFingerprints: Readonly<Record<string, ExceptionFingerprint>> = \{[\s\S]*?\n\};/;
  if (!mapPattern.test(originalSource)) throw new Error("Could not find the exception fingerprint map");
  const entries = [...fingerprints]
    .map(
      ([scope, { fingerprint, snapshot }]) =>
        `  ${JSON.stringify(scope)}: {\n    fingerprint: "${fingerprint}",\n    snapshot: "${snapshot}",\n  },`,
    )
    .join("\n");
  const source = originalSource.replace(
    mapPattern,
    `const exceptionFingerprints: Readonly<Record<string, ExceptionFingerprint>> = {\n${entries}\n};`,
  );

  if (source !== originalSource) writeFileSync(TEST_FILE, source);
}

describe("admin colour tokens", () => {
  it("reports added, removed, and changed raw-colour entries", () => {
    const expected = matchesFromSources([
      {
        file: "components/Example.tsx",
        source: 'const changed = "#111111";\nconst removed = "#222222";',
      },
    ]).map(rawColourEntry);
    const actual = matchesFromSources([
      {
        file: "components/Example.tsx",
        source: 'const changed = "#333333";\nconst added = "#444444";',
      },
    ]).map(rawColourEntry);

    const diff = diffRawColourEntries(expected, actual);

    expect(diff).toContain('Added:\n  + components/Example.tsx: #444444 in "const added = "#444444";"');
    expect(diff).toContain('Removed:\n  - components/Example.tsx: #222222 in "const removed = "#222222";"');
    expect(diff).toContain(
      'Changed:\n  ~ components/Example.tsx: #111111 -> #333333 (const changed = "#333333";)',
    );
  });

  it("defines Slate as the shared admin secondary colour", () => {
    const css = readFileSync(join(SRC_ROOT, "index.css"), "utf8");
    expect(css).toContain("--admin-slate: #4A6080;");
  });

  it("does not hardcode a colour that has an admin token", () => {
    const failures = rawColourMatches().filter(
      (match) =>
        TOKEN_EQUIVALENT_RAW_COLOURS.has(match.value.toLowerCase()) ||
        !documentedRawColourAllowList.some((exception) => exceptionMatches(exception, match)),
    );

    expect(failures).toEqual([]);
  });

  it("has no undocumented raw colours in admin pages or components", () => {
    const matches = rawColourMatches();
    const failures = matches.filter(
      (match) =>
        TOKEN_EQUIVALENT_RAW_COLOURS.has(match.value.toLowerCase()) ||
        !documentedRawColourAllowList.some((exception) => exceptionMatches(exception, match)),
    );
    const breakdown = Object.entries(
      matches.reduce<Record<string, number>>((counts, match) => {
        const directory = match.file.split("/")[0];
        counts[directory] = (counts[directory] ?? 0) + 1;
        return counts;
      }, {}),
    )
      .map(([directory, count]) => `${directory}: ${count}`)
      .join(", ");

    expect(
      failures.map((match) => `${match.file}:${match.line} ${match.value}`),
      `${matches.length} raw colours scanned (${breakdown})`,
    ).toEqual([]);
  });

  it("keeps every raw-colour exception active, documented, and exact", () => {
    const matches = rawColourMatches();
    const fingerprints = new Map<string, ExceptionFingerprint>();
    for (const exception of documentedRawColourAllowList) {
      expect(exception.scope).not.toBe("");
      expect(exception.reason).not.toBe("");
      expect(
        matches.some((match) => exceptionMatches(exception, match)),
        `Stale raw-colour exception: ${exception.scope}`,
      ).toBe(true);
      const current = matches.filter((match) => exceptionMatches(exception, match));
      fingerprints.set(exception.scope, {
        fingerprint: fingerprintFor(current),
        snapshot: encodeSnapshot(current),
      });
    }

    if (UPDATE_COLOUR_FINGERPRINTS) rewriteFingerprintMap(fingerprints);

    for (const exception of documentedRawColourAllowList) {
      const current = matches.filter((match) => exceptionMatches(exception, match));
      const fingerprint = fingerprints.get(exception.scope);
/*
      const fingerprint = createHash("sha256")
        .update(
          matches
            .filter((match) => exceptionMatches(exception, match))
            .map(
              (match) =>
                `${match.file}:${match.value.toLowerCase()}:${match.lineText.trim()}`,
            )
            .sort()
            .join("\n"),
        )
        .digest("hex");
*/
      const expected = exceptionFingerprints[exception.scope];
      const expectedFingerprint = UPDATE_COLOUR_FINGERPRINTS
        ? fingerprint?.fingerprint
        : expected.fingerprint;
      expect(
        fingerprint?.fingerprint,
        !UPDATE_COLOUR_FINGERPRINTS && fingerprint?.fingerprint !== expectedFingerprint
          ? fingerprintFailureMessage(exception, expected, current)
          : undefined,
      ).toBe(expectedFingerprint);
    }
  });
});
